// Mengambil data dari Form Trigger dan menyiapkan metadata CV.
// File binary tetap dipertahankan agar dapat dibaca oleh Extract from File.
const items = $input.all();

for (const item of items) {
  const binaryKeys = Object.keys(item.binary ?? {});
  if (binaryKeys.length === 0) {
    throw new Error('File CV tidak ditemukan. Pastikan pelamar mengunggah CV PDF.');
  }

  const binaryKey = binaryKeys[0];
  const binaryData = item.binary[binaryKey];

  item.json = {
    ...item.json,
    cv_binary_property: binaryKey,
    cv_file_name: binaryData.fileName || 'CV.pdf',
    cv_mime_type: binaryData.mimeType || 'application/pdf',
    cv_base64: binaryData.data || '',
    submitted_at: new Date().toLocaleString('id-ID', {
      timeZone: 'Asia/Jakarta',
      dateStyle: 'full',
      timeStyle: 'long'
    })
  };
}

return items;

// Membersihkan output LLM dan mengubahnya menjadi JSON object yang valid.
const items = $input.all();

function extractText(json) {
  return json.text ?? json.response ?? json.output ?? json.content ?? '';
}

for (const item of items) {
  const raw = extractText(item.json);
  item.json.raw_output = raw;

  try {
    let cleaned = String(raw).trim();
    cleaned = cleaned.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');

    const firstBrace = cleaned.indexOf('{');
    const lastBrace = cleaned.lastIndexOf('}');
    if (firstBrace !== -1 && lastBrace !== -1) {
      cleaned = cleaned.slice(firstBrace, lastBrace + 1);
    }

    const parsed = JSON.parse(cleaned);
    const score = Number(parsed.score);

    item.json = {
      ...item.json,
      candidate_name: parsed.candidate_name || 'Tidak dicantumkan',
      email: parsed.email || 'Tidak dicantumkan',
      years_of_experience: parsed.years_of_experience || 'Tidak dicantumkan',
      ai_skills: Array.isArray(parsed.top_skills) ? parsed.top_skills : [],
      ai_summary: parsed.summary || 'Tidak ada ringkasan.',
      ai_score: Number.isFinite(score) ? Math.max(0, Math.min(100, score)) : 0,
      hiring_recommendation: parsed.hiring_recommendation || 'Perlu ditinjau manual',
      strengths: Array.isArray(parsed.strengths) ? parsed.strengths : [],
      gaps: Array.isArray(parsed.gaps) ? parsed.gaps : [],
      parse_status: 'success'
    };
  } catch (error) {
    item.json = {
      ...item.json,
      error: 'Gagal parsing JSON dari AI: ' + error.message,
      parse_status: 'failed',
      ai_skills: [],
      ai_summary: 'Output AI tidak dapat dibaca. Periksa raw_output.',
      ai_score: 0,
      hiring_recommendation: 'Perlu ditinjau manual'
    };
  }
}

return items;
